  if (existing && isLive(existing)) {
    // Already a current member: the invitation is spent, but nothing about
    // their membership — role, seat, join date — changes.
    await invitationRepo.markInvitationAccepted(
      invitation.orgId,
      invitation.id,
      now,
    );
    return existing;
  }

  const member = existing
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        now,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    now,
  );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

