import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Work can only be handed to someone who currently holds a seat in the org —
 * a former member is refused outright, same as anyone who was never a member.
 */
async function assertAssignableMember(
  orgId: OrgId,
  assigneeId: UserId,
): Promise<void> {
  const member = await memberRepo.findMember(orgId, assigneeId);
  if (!member || member.status !== "active" || !isLive(member)) {
    throw new Error("Cannot assign an issue to someone who is not a member of this organization");
  }
}

